  for (const entry of entries) {
    const childUrl = new URL(`${entry.name}${entry.isDirectory() ? "/" : ""}`, dirUrl);
    if (entry.isDirectory()) {
      yield* walkMarkdown(childUrl);
    } else if (entry.name.endsWith(".md")) {
      yield childUrl;
    }
  }
}

