async function* walk(dir){let e;try{e=await readdir(dir,{withFileTypes:true});}catch{return;} for(const x of e){if(['node_modules','tmp','site','.claude'].includes(x.name)||x.isSymbolicLink()) continue; const f=path.join(dir,x.name); if(x.isDirectory()) yield* walk(f); else if(x.isFile()&&x.name.endsWith('.md')) yield f;}}
function stripFences(content){const lines=content.split(/\r?\n/); let inf=false, fence=''; return lines.map(line=>{const m=line.trim().match(/^(```|~~~)/); if(m){ if(!inf){inf=true; fence=m[1];} else if(line.trim().startsWith(fence)){inf=false; fence='';} return ''; } return inf?'':line;}).join('\n');}
function ownedTextFrom(line, markerRe){return line.replace(markerRe,'').replace(/`[A-Z][A-Z0-9-]*`/g,'').replace(/[|]/g,' ').replace(/\s+/g,' ').trim();}
function extractOwnedText(content,id){const marker=new RegExp(`<!--\\s*rule:\\s*${id}\\s*-->`); const lines=content.split(/\r?\n/); const idx=lines.findIndex(l=>marker.test(l)); let t=idx<0?'':ownedTextFrom(lines[idx],marker); if(!t && idx>=0){ const next=lines.slice(idx+1).find(l=>l.trim()); t=ownedTextFrom(next||'',marker);} return t;}
const files=[]; for(const r of roots) for await(const f of walk(r)) files.push(f);
const contents=Object.fromEntries(await Promise.all(files.map(async f=>[f, await readFile(f,'utf8')])));
const ruleRe=/<!--\s*rule:\s*([A-Z][A-Z0-9-]*)\s*-->/g; const defs=[];
for(const [file,s] of Object.entries(contents)) for(const m of stripFences(s).matchAll(ruleRe)) defs.push({id:m[1], file});
const findings=[];
for(const def of defs){ const text=extractOwnedText(contents[def.file], def.id); if(text.length < 24) continue; for(const [file,s] of Object.entries(contents)){ if(file===def.file) continue; if(s.includes(text)) findings.push(`${def.id}: ${def.file} restated in ${file}`); }}
console.log(`rules checked=${defs.length}`); console.log(`exact owned-text restatements=${findings.length}`); for(const f of findings) console.log(`- ${f}`);
