        if 'vendor' in str(f): continue
        sources.append((str(f), f.read_text()))
regex_re=re.compile(r'/(?:\\/|[^/]){50,}/[a-z]*')
def unescape(pat):
    body=pat[1:pat.rfind('/')]
    for a,b in [(r'\/', '/'), (r'\.', '.'), (r'\-', '-'), (r'\(', '('), (r'\)', ')'), (r'\[','['), (r'\]',']'), (r'\|','|'), (r'\`','`')]: body=body.replace(a,b)
    return body
findings=[]
for tf in sorted(Path('test/contracts').glob('*.mjs')):
    for i,line in enumerate(tf.read_text().splitlines(),1):
        for m in regex_re.finditer(line.strip()):
            lit=unescape(m.group())
            if any(tok in lit for tok in ['[\\s\\S]', '.*', '.+', '\\s', '\\n', '?=', '^', '$', '{', '}']): continue
            if not re.search(r'[.!?]$', lit): continue
            if not re.search(r'\b(must|MUST|must not|MUST NOT|Do not|do not|Never|never|required|requires|Before|If|When|only|Every)\b', lit): continue
            hits=[sf for sf,txt in sources if lit in txt]
            if hits: findings.append((str(tf),i,lit,hits[0]))
print(f'exact sentence pins with normative-doc hits={len(findings)}')
for tf,i,lit,h in findings:
    print(f'- {tf}:{i} -> {h} :: {lit}')
